namespace Aster {
public class NetworkResult {
 public string TimeUtc,Profile,Provider="Cloudflare HTTPS",Method="Sequential requests; full request duration";public double LatencyMs,VariationMs;public double? DownloadMbps,UploadMbps;public long PayloadBytes;
 public string Summary(){return "Test completed: "+TimeUtc+"\r\n"+Profile+" · "+Provider+"\r\nHTTPS latency: "+LatencyMs.ToString("F1")+" ms · variation: "+VariationMs.ToString("F1")+" ms\r\nDownload: "+(DownloadMbps.HasValue?DownloadMbps.Value.ToString("F2")+" Mbps":"not tested")+"\r\nUpload: "+(UploadMbps.HasValue?UploadMbps.Value.ToString("F2")+" Mbps":"not tested")+"\r\nPayload transferred: "+(PayloadBytes/1048576.0).ToString("F1")+" MiB (excludes protocol overhead)\r\n\r\nSingle-connection HTTPS estimates to this provider. Request timing includes network/server overhead; short tests may underestimate fast links. VPNs, Wi-Fi, congestion and competing apps can affect results. Variation is successive HTTPS timing differences, not packet loss or an ICMP ping.";}
}
class NetworkProfile {
 public string Name;public int DownloadBytes,UploadBytes;
 public long Budget{get{return 3L*(DownloadBytes+UploadBytes);}}
 public override string ToString(){return Name;}
 public static NetworkProfile[] All={new NetworkProfile{Name="Quick · about 18 MiB",DownloadBytes=4*1048576,UploadBytes=2*1048576},new NetworkProfile{Name="Standard · about 72 MiB",DownloadBytes=16*1048576,UploadBytes=8*1048576},new NetworkProfile{Name="Latency only · minimal data"}};
}
static class NetworkMeasure {
 public static double Median(IEnumerable<double> values){var v=values.OrderBy(x=>x).ToArray();if(v.Length==0)throw new Exception("No samples.");return v.Length%2==1?v[v.Length/2]:(v[v.Length/2-1]+v[v.Length/2])/2;}
 public static double Mbps(long bytes,double seconds){if(bytes<0||seconds<=0)throw new ArgumentException("Invalid throughput sample.");return bytes*8.0/seconds/1000000;}
 public static double Variation(double[] values){return values.Length<2?0:Enumerable.Range(1,values.Length-1).Average(i=>Math.Abs(values[i]-values[i-1]));}
 public static HttpClient Client(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false,AutomaticDecompression=DecompressionMethods.None,UseCookies=false}){BaseAddress=new Uri("https://speed.cloudflare.com/"),Timeout=Timeout.InfiniteTimeSpan,MaxResponseContentBufferSize=65536};client.DefaultRequestHeaders.AcceptEncoding.ParseAdd("identity");client.DefaultRequestHeaders.CacheControl=new CacheControlHeaderValue{NoCache=true,NoStore=true};return client;}
 public static async Task<NetworkResult> Run(HttpClient client,NetworkProfile profile,IProgress<string> progress,CancellationToken cancel){using(var total=CancellationTokenSource.CreateLinkedTokenSource(cancel)){total.CancelAfter(TimeSpan.FromMinutes(3));var ct=total.Token;var times=new List<double>();for(int i=0;i<6;i++){progress.Report(i==0?"Warming the HTTPS connection…":"HTTPS latency sample "+i+" / 5");double duration=await Download(client,0,ct);if(i>0)times.Add(duration*1000);}var result=new NetworkResult{Profile=profile.Name,TimeUtc=DateTimeOffset.UtcNow.ToString("o"),LatencyMs=Median(times),VariationMs=Variation(times.ToArray())};if(profile.DownloadBytes>0){var down=new List<double>();for(int i=0;i<3;i++){ct.ThrowIfCancellationRequested();progress.Report("Download sample "+(i+1)+" / 3 · "+profile.DownloadBytes/1048576+" MiB");down.Add(Mbps(profile.DownloadBytes,await Download(client,profile.DownloadBytes,ct)));result.PayloadBytes+=profile.DownloadBytes;}result.DownloadMbps=Median(down);}if(profile.UploadBytes>0){var payload=new byte[profile.UploadBytes];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(payload);var up=new List<double>();for(int i=0;i<3;i++){ct.ThrowIfCancellationRequested();progress.Report("Upload sample "+(i+1)+" / 3 · "+profile.UploadBytes/1048576+" MiB of generated test data");up.Add(Mbps(payload.Length,await Upload(client,payload,ct)));result.PayloadBytes+=payload.Length;}result.UploadMbps=Median(up);}ct.ThrowIfCancellationRequested();return result;}}
 static async Task<double> Download(HttpClient client,int bytes,CancellationToken token){using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(TimeSpan.FromSeconds(30));var ct=timeout.Token;var watch=Stopwatch.StartNew();using(var request=new HttpRequestMessage(HttpMethod.Get,"__down?bytes="+bytes+"&aster="+Guid.NewGuid().ToString("N")))using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentEncoding.Any())throw new Exception("Unexpected compressed response; throughput was not measured.");using(ct.Register(()=>response.Dispose()))using(var stream=await response.Content.ReadAsStreamAsync()){var buffer=new byte[65536];long received=0;int read;while((read=await stream.ReadAsync(buffer,0,buffer.Length,ct))>0){received+=read;if(received>bytes)throw new Exception("Unexpected response size; test stopped.");}if(received!=bytes)throw new Exception("Incomplete download; no throughput result recorded.");}watch.Stop();ct.ThrowIfCancellationRequested();return Math.Max(.000001,watch.Elapsed.TotalSeconds);}}}
 static async Task<double> Upload(HttpClient client,byte[] payload,CancellationToken token){using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(TimeSpan.FromSeconds(30));var ct=timeout.Token;var watch=Stopwatch.StartNew();using(var request=new HttpRequestMessage(HttpMethod.Post,"__up")){request.Content=new ByteArrayContent(payload);request.Content.Headers.ContentType=new MediaTypeHeaderValue("application/octet-stream");using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct)){response.EnsureSuccessStatusCode();using(ct.Register(()=>response.Dispose()))using(var stream=await response.Content.ReadAsStreamAsync()){var buffer=new byte[4096];int read,total=0;while((read=await stream.ReadAsync(buffer,0,buffer.Length,ct))>0){total+=read;if(total>65536)throw new Exception("Unexpected upload response size.");}}watch.Stop();ct.ThrowIfCancellationRequested();return Math.Max(.000001,watch.Elapsed.TotalSeconds);}}}}
}
static class NetworkHistory {
 public static string FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","NetworkHistory.json");
 public static List<NetworkResult> Read(){if(!File.Exists(FileName))return new List<NetworkResult>();if(new FileInfo(FileName).Length>1048576)throw new Exception("History file exceeds 1 MB.");var items=new JavaScriptSerializer{MaxJsonLength=1048576}.Deserialize<List<NetworkResult>>(File.ReadAllText(FileName));if(items==null||items.Count>50||items.Any(x=>x==null))throw new Exception("Invalid history file.");return items;}
 public static void Add(NetworkResult value){var history=Read();history.Insert(0,value);history=history.Take(50).ToList();Directory.CreateDirectory(Path.GetDirectoryName(FileName));string temp=FileName+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(history),Encoding.UTF8);if(File.Exists(FileName))File.Replace(temp,FileName,null);else File.Move(temp,FileName);}
}
class NetworkPanel:UserControl {
 CancellationTokenSource cancellation;Button start;TextBox output;Label state;ComboBox profiles;ListBox history;MetricTile down,up,latency;NetworkResult latest;
 public NetworkPanel(){Dock=DockStyle.Fill;var tabs=new TabControl{Dock=DockStyle.Fill};Controls.Add(tabs);var test=new TabPage("Speed test");var connections=new TabPage("Connection details");var records=new TabPage("Saved results");tabs.TabPages.AddRange(new[]{test,connections,records});var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(12)};foreach(int height in new[]{82,50,145,36})root.RowStyles.Add(new RowStyle(SizeType.Absolute,height));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));test.Controls.Add(root);root.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Connects to speed.cloudflare.com when you click Start. Cloudflare receives your network address and generated test traffic; no personal files are uploaded. Quick uses about 18 MiB; Standard about 72 MiB, plus protocol overhead. Latency-only sends small HTTPS requests.\r\nThese are sequential HTTPS estimates, not a guaranteed maximum line speed.",AutoEllipsis=true},0,0);var controls=new FlowLayoutPanel{Dock=DockStyle.Fill};profiles=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=260};profiles.Items.AddRange(NetworkProfile.All);profiles.SelectedIndex=0;controls.Controls.Add(profiles);start=B("Start test");start.Click+=async(s,e)=>await RunTest();controls.Controls.Add(start);var stop=B("Cancel");stop.Click+=(s,e)=>{if(cancellation!=null)cancellation.Cancel();};controls.Controls.Add(stop);var copy=B("Copy last result");copy.Click+=(s,e)=>{if(latest!=null)try{Clipboard.SetText(latest.Summary());}catch(Exception ex){state.Text=ex.Message;}};controls.Controls.Add(copy);root.Controls.Add(controls,0,1);var tiles=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3};for(int i=0;i<3;i++)tiles.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.333f));down=new MetricTile{Caption="DOWNLOAD",Detail="Mbps · median of 3 samples",Accent=Color.FromArgb(105,212,240)};up=new MetricTile{Caption="UPLOAD",Detail="Mbps · median of 3 samples",Accent=Color.FromArgb(186,159,253)};latency=new MetricTile{Caption="HTTPS LATENCY",Detail="ms · median of 5 samples",Accent=Color.FromArgb(113,225,187)};tiles.Controls.Add(down,0,0);tiles.Controls.Add(up,1,0);tiles.Controls.Add(latency,2,0);root.Controls.Add(tiles,0,2);state=new Label{Dock=DockStyle.Fill,Text="Ready · no test traffic until Start"};root.Controls.Add(state,0,3);output=TextArea();output.Text="For comparisons, use the same test profile and connection. Pause downloads yourself if you want a less busy measurement. Leaving this page or closing Aster cancels the test. Only completed results are saved locally.";root.Controls.Add(output,0,4);
 var cr=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Padding=new Padding(12)};cr.RowStyles.Add(new RowStyle(SizeType.Absolute,50));cr.RowStyles.Add(new RowStyle(SizeType.Percent,100));connections.Controls.Add(cr);var details=TextArea();details.Text="Click Refresh to read local adapter details. This sends no internet test traffic.";var refresh=B("Refresh local connections");refresh.Click+=(s,e)=>details.Text=ConnectionDetails();cr.Controls.Add(refresh,0,0);cr.Controls.Add(details,0,1);
 var hr=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(12)};hr.RowStyles.Add(new RowStyle(SizeType.Absolute,50));hr.RowStyles.Add(new RowStyle(SizeType.Absolute,180));hr.RowStyles.Add(new RowStyle(SizeType.Percent,100));records.Controls.Add(hr);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var reload=B("Refresh history");reload.Click+=(s,e)=>LoadHistory();actions.Controls.Add(reload);var export=B("Export history as CSV");export.Click+=(s,e)=>ExportHistory();actions.Controls.Add(export);hr.Controls.Add(actions,0,0);history=new ListBox{Dock=DockStyle.Fill};hr.Controls.Add(history,0,1);var detail=TextArea();hr.Controls.Add(detail,0,2);history.SelectedIndexChanged+=(s,e)=>{var item=history.SelectedItem as ResultItem;if(item!=null)detail.Text=item.Value.Summary();};LoadHistory();}
 class ResultItem{public NetworkResult Value;public override string ToString(){return Value.TimeUtc+" · "+Value.Profile+" · ↓ "+(Value.DownloadMbps.HasValue?Value.DownloadMbps.Value.ToString("F1"):"—")+" / ↑ "+(Value.UploadMbps.HasValue?Value.UploadMbps.Value.ToString("F1"):"—")+" Mbps";}}
 static Button B(string text){return new ThemeButton{Text=text,AutoSize=true,Height=34,FlatStyle=FlatStyle.Flat,Padding=new Padding(10,2,10,2),Margin=new Padding(0,2,10,2)};}
 static TextBox TextArea(){return new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Font=new Font("Segoe UI",10),BorderStyle=BorderStyle.None};}
 async Task RunTest(){start.Enabled=false;profiles.Enabled=false;latest=null;down.Value=up.Value=latency.Value="—";foreach(var tile in new[]{down,up,latency})tile.Invalidate();cancellation=new CancellationTokenSource();output.Text="Running… Values appear only after a complete test.";try{using(var client=NetworkMeasure.Client()){var progress=new Progress<string>(message=>{if(!IsDisposed)state.Text=message;});latest=await NetworkMeasure.Run(client,(NetworkProfile)profiles.SelectedItem,progress,cancellation.Token);}if(IsDisposed)return;down.Value=latest.DownloadMbps.HasValue?latest.DownloadMbps.Value.ToString("F1"):"—";up.Value=latest.UploadMbps.HasValue?latest.UploadMbps.Value.ToString("F1"):"—";latency.Value=latest.LatencyMs.ToString("F1");foreach(var tile in new[]{down,up,latency})tile.Invalidate();output.Text=latest.Summary();try{NetworkHistory.Add(latest);state.Text="Completed · saved locally · results are estimates";LoadHistory();}catch(Exception ex){state.Text="Completed, but history could not be saved: "+ex.Message;}}catch(Exception ex){if(!IsDisposed){bool stopped=cancellation.IsCancellationRequested||ex is OperationCanceledException;state.Text=stopped?"Canceled or timed out · no completed result saved":"Test failed · no completed result saved";output.Text=stopped?"The test stopped. Partial traffic may already have been transferred.":ex.Message+"\r\nThe provider, firewall, proxy or connection may be unavailable. This does not prove your internet is disconnected.";}}finally{if(!IsDisposed){start.Enabled=true;profiles.Enabled=true;}cancellation.Dispose();cancellation=null;}}
 void LoadHistory(){try{history.Items.Clear();foreach(var item in NetworkHistory.Read())history.Items.Add(new ResultItem{Value=item});if(history.Items.Count>0)history.SelectedIndex=0;}catch(Exception ex){history.Items.Add("History unavailable: "+ex.Message);}}
 void ExportHistory(){try{var values=NetworkHistory.Read();using(var d=new SaveFileDialog{Filter="CSV file|*.csv",FileName="Aster-network-history.csv"})if(d.ShowDialog(this)==DialogResult.OK){Func<string,string> csv=v=>"\""+(v??"").Replace("\"","\"\"")+"\"";var lines=new List<string>{"Time UTC,Profile,Download Mbps,Upload Mbps,HTTPS latency ms,Variation ms,Payload bytes"};lines.AddRange(values.Select(v=>string.Join(",",new[]{v.TimeUtc,v.Profile,Convert.ToString(v.DownloadMbps,System.Globalization.CultureInfo.InvariantCulture),Convert.ToString(v.UploadMbps,System.Globalization.CultureInfo.InvariantCulture),v.LatencyMs.ToString(System.Globalization.CultureInfo.InvariantCulture),v.VariationMs.ToString(System.Globalization.CultureInfo.InvariantCulture),v.PayloadBytes.ToString()}.Select(csv))));File.WriteAllLines(d.FileName,lines,Encoding.UTF8);}}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
 public static string ConnectionDetails(){var b=new StringBuilder("LOCAL ADAPTERS · not an internet connectivity test\r\nLink speed is the adapter's reported rate, not your measured internet speed.\r\n\r\n");try{foreach(var adapter in NetworkInterface.GetAllNetworkInterfaces()){b.AppendLine(adapter.Name+" · "+adapter.NetworkInterfaceType+" · "+adapter.OperationalStatus);try{b.AppendLine("Reported link: "+(adapter.Speed/1000000.0).ToString("F0")+" Mbps");var ip=adapter.GetIPProperties();b.AppendLine("Local addresses: "+string.Join(", ",ip.UnicastAddresses.Select(a=>a.Address.ToString())));b.AppendLine("Gateways: "+string.Join(", ",ip.GatewayAddresses.Select(a=>a.Address.ToString())));b.AppendLine("DNS servers: "+string.Join(", ",ip.DnsAddresses.Select(a=>a.ToString())));}catch(Exception ex){b.AppendLine("Details unavailable: "+ex.Message);}b.AppendLine();}}catch(Exception ex){b.AppendLine("Adapter inventory unavailable: "+ex.Message);}return b.ToString();}
 protected override void Dispose(bool disposing){if(disposing&&cancellation!=null)cancellation.Cancel();base.Dispose(disposing);}
}
partial class MainWindow {void BuildNetworkLab(){sub.Text="On-demand HTTPS speed estimates · local connection details · result history";content.Controls.Add(new NetworkPanel());}}
